ON CONFLICT (group_key, version) DO UPDATE SET
  published = EXCLUDED.published,
  spec = EXCLUDED.spec;

COMMIT;

-- Post-insertion verification query
SELECT
  group_key,
  version,
  published,
  spec->>'source_workbook' AS source_workbook,
  (spec->>'total_questions')::int AS total_questions,
  (spec->>'total_cached_marks')::int AS total_cached_marks,
  jsonb_array_length(spec->'sections') AS sections_count
FROM public.jmcwc_papers
WHERE version = '2026.1'
ORDER BY group_key;
